static long long comb(int n, int m, long long *calls)
{
    ++(*calls);
    if (m == 0 || m == n)
        return 1;
    return comb(n - 1, m - 1, calls) + comb(n - 1, m, calls);
}

int main(void)
{
    int n, m;
    long long calls = 0;

    if (scanf("%d %d", &n, &m) != 2 || n < 0 || m < 0 || m > n || n > 20)
        return 0;

    printf("%lld\n", comb(n, m, &calls));
    printf("%lld\n", calls);
    return 0;
}

