static long long isqrt_rec(long long n, long long lo, long long hi, int *cmp)
{
    long long mid;

    if (lo > hi)
        return hi;
    mid = lo + (hi - lo) / 2;
    ++(*cmp);
    if (mid * mid <= n)
        return isqrt_rec(n, mid + 1, hi, cmp);
    return isqrt_rec(n, lo, mid - 1, cmp);
}

