        return 0;

    hi = (n < 46340) ? n : 46340;
    r = isqrt_rec(n, 0, hi, &cmp);
    printf("%lld\n", r);
    printf("%s\n", r * r == n ? "YES" : "NO");
    printf("%d\n", cmp);
    return 0;
}

