#include <stdio.h>

#define MAXN 100000

static long long a[MAXN];

static void solve(int left, int right, long long *mx, long long *mn, long long *cmp)
{
    int mid;
    long long mx1, mn1, mx2, mn2;

    if (left == right) {
        *mx = a[left];
        *mn = a[left];
        return;
    }
    if (right == left + 1) {
        ++(*cmp);
        if (a[left] > a[right]) {
            *mx = a[left];
            *mn = a[right];
        } else {
            *mx = a[right];
            *mn = a[left];
        }
        return;
    }

    mid = left + (right - left) / 2;
    solve(left, mid, &mx1, &mn1, cmp);
    solve(mid + 1, right, &mx2, &mn2, cmp);

    ++(*cmp);
    *mx = (mx1 > mx2) ? mx1 : mx2;
    ++(*cmp);
    *mn = (mn1 < mn2) ? mn1 : mn2;
}

int main(void)
{
    int n, i;
    long long mx = 0, mn = 0, cmp = 0;

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%lld", &a[i]) != 1)
            return 0;
    }

    solve(0, n - 1, &mx, &mn, &cmp);
    printf("%lld\n", mx);
    printf("%lld\n", mn);
    printf("%lld\n", cmp);
    return 0;
}

