#include <stdio.h>

#define MAXN 200000

static long long a[MAXN];
static long long tmp[MAXN];

static long long merge_sort(int lo, int hi)
{
    int mid, i, j, k;
    long long cnt = 0;

    if (lo >= hi)
        return 0;

    mid = lo + (hi - lo) / 2;
    cnt += merge_sort(lo, mid);
    cnt += merge_sort(mid + 1, hi);

    i = lo;
    j = mid + 1;
    k = lo;
    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
            cnt += (long long)(mid - i + 1);
        }
    }
    while (i <= mid)
        tmp[k++] = a[i++];
    while (j <= hi)
        tmp[k++] = a[j++];

    for (k = lo; k <= hi; k++)
        a[k] = tmp[k];
    return cnt;
}

int main(void)
{
    int n, i;

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%lld", &a[i]) != 1)
            return 0;
    }

    printf("%lld\n", merge_sort(0, n - 1));
    return 0;
}

