#include <iostream>
#include <vector>

static long long merge_sort(std::vector<long long> &a, std::vector<long long> &tmp,
                            int lo, int hi)
{
    if (lo >= hi)
        return 0;

    int mid = lo + (hi - lo) / 2;
    long long cnt = merge_sort(a, tmp, lo, mid) + merge_sort(a, tmp, mid + 1, hi);

    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        if (a[static_cast<std::size_t>(i)] <= a[static_cast<std::size_t>(j)]) {
            tmp[static_cast<std::size_t>(k++)] = a[static_cast<std::size_t>(i++)];
        } else {
            tmp[static_cast<std::size_t>(k++)] = a[static_cast<std::size_t>(j++)];
            cnt += static_cast<long long>(mid - i + 1);
        }
    }
    while (i <= mid)
        tmp[static_cast<std::size_t>(k++)] = a[static_cast<std::size_t>(i++)];
    while (j <= hi)
        tmp[static_cast<std::size_t>(k++)] = a[static_cast<std::size_t>(j++)];

    for (k = lo; k <= hi; ++k)
        a[static_cast<std::size_t>(k)] = tmp[static_cast<std::size_t>(k)];
    return cnt;
}

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    if (!(std::cin >> n) || n < 1 || n > 200000)
        return 0;

    std::vector<long long> a(static_cast<std::size_t>(n));
    std::vector<long long> tmp(static_cast<std::size_t>(n));
    for (int i = 0; i < n; ++i)
        std::cin >> a[static_cast<std::size_t>(i)];

    std::cout << merge_sort(a, tmp, 0, n - 1) << '\n';
    return 0;
}

