#include <ctype.h>

typedef enum { ST_NONE, ST_NUM, ST_WORD } State;

int main(void)
{
    char line[256];
    State state = ST_NONE;
    int num_cnt = 0, word_cnt = 0, sym_cnt = 0;
    int cur_len = 0, max_len = 0;
    const char *p;

    if (fgets(line, (int)sizeof line, stdin) == NULL)
        return 0;

    for (p = line; *p != '\0'; p++) {
        unsigned char ch = (unsigned char)*p;

        if (ch == '\n' || ch == '\r')
            break;
        if (ch == ' ') {
            state = ST_NONE;
            cur_len = 0;
        } else if (isdigit(ch)) {
            if (state != ST_NUM) {
                ++num_cnt;
                cur_len = 1;
                state = ST_NUM;
            } else {
                ++cur_len;
            }
            if (cur_len > max_len)
                max_len = cur_len;
        } else if (isalpha(ch)) {
            if (state != ST_WORD) {
                ++word_cnt;
                state = ST_WORD;
            }
        } else {
            ++sym_cnt;
            state = ST_NONE;
            cur_len = 0;
        }
    }

    printf("num: %d\n", num_cnt);
    printf("word: %d\n", word_cnt);
    printf("sym: %d\n", sym_cnt);
    printf("maxlen: %d\n", max_len);
    return 0;
}

