            cur_len = 0
        elif "0" <= ch <= "9":
            if state is not State.NUM:
                num_cnt += 1
                cur_len = 1
                state = State.NUM
            else:
                cur_len += 1
            if cur_len > max_len:
                max_len = cur_len
        elif is_alpha(ch):
            if state is not State.WORD:
                word_cnt += 1
                state = State.WORD
