#include <stdio.h>

typedef enum {
    PERM_READ   = 1 << 0,
    PERM_WRITE  = 1 << 1,
    PERM_EXEC   = 1 << 2,
    PERM_DELETE = 1 << 3,
    PERM_ADMIN  = 1 << 4
} Perm;

#define PERM_ALL (PERM_READ | PERM_WRITE | PERM_EXEC | PERM_DELETE | PERM_ADMIN)

#define MAXN 1000

static int popcount(unsigned int v)
{
    int c = 0;

    while (v != 0u) {
        v &= v - 1u;
        ++c;
    }
    return c;
}

int main(void)
{
    int n, q, i;
    int masks[MAXN];
    int cnt_all = 0, cnt_any = 0, cnt_none = 0, bits = 0;

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &masks[i]) != 1)
            return 0;
    }
    if (scanf("%d", &q) != 1 || q < 1 || q > PERM_ALL)
        return 0;

    for (i = 0; i < n; i++) {
        unsigned int mask = (unsigned int)masks[i];
        unsigned int want = (unsigned int)q;
        unsigned int hit = mask & want;

        if (hit == want)
            ++cnt_all;
        if (hit != 0u)
            ++cnt_any;
        else
            ++cnt_none;
        bits += popcount(mask);
    }

    printf("all: %d\n", cnt_all);
    printf("any: %d\n", cnt_any);
    printf("none: %d\n", cnt_none);
    printf("popcount: %d\n", bits);
    return 0;
}

